import math
seen=set()
start=None
def control(obs):
    global start
    if start is None: start=obs['t']
    phase=int((obs['t']-start)/2.5)
    gaze=-64 if phase%2==0 else -125
    if obs['head']['settled'] and phase not in seen:
        seen.add(phase)
        for name,view in obs['views'].items():
            pts=[]
            for b,d in view['walls']:
                a=math.radians(b); o=view['origin']
                x=o[0]+d*math.cos(a); y=o[1]+d*math.sin(a)
                if -14<x<5: pts.append((round(x,1),round(y,1)))
            print('RAILS',round(obs['progress']['covered'],1),name,pts)
    h=obs['hitch_deg']
    steer=max(-30,min(30,0.51*h+2.2*(h-21)))
    return (steer,-0.35,gaze)

